const manifest={model:'VX8',version:'1.0.28',filename:'test.bin',public_url:'https://example.invalid/test.bin',file_size:1,checksum_sha256:'abc'};
test('install opens a fresh code card before downloading or writing firmware',()=>{
  const {ctx,requests,events}=context();ctx.installOtaUpdate(manifest);
  assert.equal(ctx.title,'Authorize firmware update');assert.equal(ctx.$('#otaCode').value,'');
  assert.match(ctx.markup,/Update code \(Settings PIN\)/);assert.equal(requests.length,0);assert.equal(events.length,0);
});
test('blank and malformed codes remain in the card without network requests',async()=>{
  const {ctx,requests}=context();ctx.installOtaUpdate(manifest);
  for(const pin of ['', '123','12345','12ab']){
    ctx.$('#otaCode').value=pin;ctx.$('#otaCodeContinue').onclick();await flush();
    assert.match(ctx.$('#otaCodeError').textContent,/four-digit/);assert.equal(requests.length,0);
  }
});
test('incorrect codes and rate limits show inline errors and permit retry',async()=>{
  for(const status of [401,429]){
    const {ctx,events}=context([{ok:false,status}]);ctx.installOtaUpdate(manifest);
    ctx.$('#otaCode').value='9876';ctx.$('#otaCodeContinue').onclick();await flush();
    assert.match(ctx.$('#otaCodeError').textContent,status===401?/Incorrect code/:/three seconds/);
    assert.equal(ctx.$('#otaCodeContinue').disabled,false);assert.deepEqual(events,[]);
  }
});
test('correct code authorizes before download and is revalidated before upload',async()=>{
  const {ctx,requests,events}=context([accepted(),{ok:true,status:200},
    {ok:true,arrayBuffer:async()=>new Uint8Array([0]).buffer},accepted()]);
  ctx.installOtaUpdate(manifest);ctx.$('#otaCode').value='9876';ctx.$('#otaCodeContinue').onclick();
  await flush();await flush();
  assert.deepEqual(requests.map(r=>r.url),['/loomx/security/unlock','/update',manifest.public_url,'/loomx/security/unlock']);
  assert.equal(requests[0].options.body,'pin=9876');assert.equal(requests[3].options.body,'pin=9876');
  assert.deepEqual(events,['begin','upload','prefs','reboot']);
});
test('the code card needs only the PIN and ignores legacy OTA lock responses',async()=>{
  const {ctx,requests}=context([{ok:true,status:200,json:async()=>({success:true,otaLocked:true})}]);
  const authorized=[];ctx.sheetOtaCode('Update',pin=>authorized.push(pin));
  assert.doesNotMatch(ctx.markup,/passphrase|otaPassRow|otaCodePass/);
  ctx.$('#otaCode').value='9876';ctx.$('#otaCodeContinue').onclick();await flush();
  assert.deepEqual(authorized,['9876']);assert.equal(requests.length,1);
  assert.equal(requests[0].url,'/loomx/security/unlock');
});
test('cancelling or closing the card never starts an update',async()=>{
  const {ctx,requests,events}=context();ctx.installOtaUpdate(manifest);ctx.$('#otaCodeCancel').onclick();
  assert.equal(requests.length,0);assert.equal(events.length,0);
  let finish;ctx.fetch=()=>new Promise(resolve=>finish=resolve);ctx.installOtaUpdate(manifest);
  ctx.$('#otaCode').value='9876';ctx.$('#otaCodeContinue').onclick();ctx.closeSheet();finish(accepted());await flush();
  assert.equal(events.length,0);assert.equal(requests.length,0);
});
test('failed checksum never writes firmware',async()=>{
  const {ctx,events}=context([accepted(),{ok:true,status:200},{ok:true,arrayBuffer:async()=>new Uint8Array([0]).buffer}]);
  ctx.sha256Hex=async()=> 'wrong';ctx.installOtaUpdate(manifest);
  ctx.$('#otaCode').value='9876';ctx.$('#otaCodeContinue').onclick();await flush();
  assert.ok(events.some(e=>e.includes('SHA-256')));assert.ok(!events.includes('upload'));
});
test('update controls are directly available and local upload presents the PIN card',()=>{
  const {ctx,requests}=context();let checked=false;ctx.checkOtaUpdate=()=>{checked=true};
  ctx.sheetFirmware();assert.doesNotMatch(ctx.markup,/otaEnable|otaDisable|OTA lock|passphrase/);
  ctx.$('#otaCheck').onclick();assert.equal(checked,true);assert.equal(requests.length,0);
  ctx.$('#otaLocal').onclick();assert.equal(ctx.title,'Authorize local update');
  assert.equal(ctx.location.href,undefined);assert.ok(ctx.$('#otaCode'));
});
test('firmware PIN endpoint validates exact codes and preserves retry cooldown',()=>{
  const server=fs.readFileSync(path.join(root,'wled00/wled_server.cpp'),'utf8');
  const start=server.indexOf('  server.on(F("/loomx/security/unlock")');
  const handler=server.slice(start,server.indexOf('  // Changes the Loomx settings PIN',start));
  const util=fs.readFileSync(path.join(root,'wled00/util.cpp'),'utf8');
  const check=util.slice(util.indexOf('void checkSettingsPIN('),util.indexOf('uint16_t crc16',util.indexOf('void checkSettingsPIN(')));
  const directory=fs.mkdtempSync(path.join(os.tmpdir(),'loomx-ota-pin-'));
  try{
    const file=path.join(directory,'test.cpp');fs.writeFileSync(file,`#include <cassert>\n#include <cstring>\n#include <cctype>\n#include <string>\n#include <functional>
#define F(x) x
#define FPSTR(x) x
#define HTTP_POST 1
using String=std::string;const char *CONTENT_TYPE_PLAIN="text/plain",*CONTENT_TYPE_JSON="application/json";
char settingsPIN[5]="9876";bool correctPIN=false;unsigned long now=10000,lastEditTime=0;
constexpr unsigned long PIN_RETRY_COOLDOWN=3000;unsigned long millis(){return now;}
${check}
struct Param{String input;String value(){return input;}};
struct AsyncWebServerRequest{Param param;int code=0;String response;
 bool hasParam(const char*,bool){return !param.input.empty();}Param* getParam(const char*,bool){return &param;}
 void send(int status,const char*,const char* body){code=status;response=body;}
};
struct {std::function<void(AsyncWebServerRequest*)> handler;void on(const char*,int,std::function<void(AsyncWebServerRequest*)> fn){handler=fn;}} server;
int main(){${handler}
 AsyncWebServerRequest request;
 request.param.input="123";server.handler(&request);assert(request.code==400);
 request.param.input="98ab";server.handler(&request);assert(request.code==400);
 request.param.input="1111";server.handler(&request);assert(request.code==401);assert(!correctPIN);
 request.param.input="9876";now+=100;server.handler(&request);assert(request.code==429);assert(!correctPIN);
 now+=3000;server.handler(&request);assert(request.code==200);assert(correctPIN);assert(request.response.find("success")!=String::npos);
 request.param.input="1111";server.handler(&request);assert(request.code==401);assert(!correctPIN);
 assert(!strcmp(settingsPIN,"9876"));
}`);
    execFileSync('c++',['-std=c++17','-Wall','-Wextra','-Werror',file,'-o',path.join(directory,'test')]);
    execFileSync(path.join(directory,'test'));
  }finally{fs.rmSync(directory,{recursive:true,force:true})}
});
